// AutoApplier In-Memory OpenXML DOCX Synthesizer
// Generates standard single-column ATS-compliant Word Documents (.docx) in pure JavaScript
// Zero external dependencies, zero network requests, zero disk I/O.

(() => {
  // --- CRC32 Lookup Table & Calculator ---
  function makeCrcTable() {
    let c;
    const table = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      c = n;
      for (let k = 0; k < 8; k++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      }
      table[n] = c >>> 0;
    }
    return table;
  }

  const crcTable = makeCrcTable();
  function crc32(uint8Array) {
    let crc = 0 ^ (-1);
    for (let i = 0; i < uint8Array.length; i++) {
      crc = (crc >>> 8) ^ crcTable[(crc ^ uint8Array[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }

  // --- Pure JS In-Memory ZIP Generator ---
  class SimpleZip {
    constructor() {
      this.files = [];
      this.encoder = new TextEncoder();
    }

    file(name, content) {
      const data = typeof content === 'string' ? this.encoder.encode(content) : content;
      this.files.push({
        name,
        data,
        crc: crc32(data)
      });
    }

    generateBlob(mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
      const parts = [];
      const cdParts = [];
      let offset = 0;

      for (const f of this.files) {
        const nameBytes = this.encoder.encode(f.name);

        // Local File Header (30 bytes + name length)
        const localHeader = new Uint8Array(30 + nameBytes.length);
        const view = new DataView(localHeader.buffer);
        view.setUint32(0, 0x04034b50, true);  // Local file header signature
        view.setUint16(4, 20, true);          // Version needed (2.0)
        view.setUint16(6, 0, true);           // Flags
        view.setUint16(8, 0, true);           // Compression: 0 (Store)
        view.setUint16(10, 0, true);          // Mod time
        view.setUint16(12, 0, true);          // Mod date
        view.setUint32(14, f.crc, true);      // CRC-32
        view.setUint32(18, f.data.length, true); // Compressed size
        view.setUint32(22, f.data.length, true); // Uncompressed size
        view.setUint16(26, nameBytes.length, true); // Filename length
        view.setUint16(28, 0, true);          // Extra field length
        localHeader.set(nameBytes, 30);

        parts.push(localHeader);
        parts.push(f.data);

        // Central Directory Header (46 bytes + name length)
        const cdHeader = new Uint8Array(46 + nameBytes.length);
        const cdView = new DataView(cdHeader.buffer);
        cdView.setUint32(0, 0x02014b50, true); // Central directory signature
        cdView.setUint16(4, 20, true);         // Version made by
        cdView.setUint16(6, 20, true);         // Version needed
        cdView.setUint16(8, 0, true);          // Flags
        cdView.setUint16(10, 0, true);         // Compression: 0
        cdView.setUint16(12, 0, true);         // Mod time
        cdView.setUint16(14, 0, true);         // Mod date
        cdView.setUint32(16, f.crc, true);     // CRC-32
        cdView.setUint32(20, f.data.length, true); // Compressed size
        cdView.setUint32(24, f.data.length, true); // Uncompressed size
        cdView.setUint16(28, nameBytes.length, true); // Filename length
        cdView.setUint16(30, 0, true);         // Extra field length
        cdView.setUint16(32, 0, true);         // File comment length
        cdView.setUint16(34, 0, true);         // Disk number start
        cdView.setUint16(36, 0, true);         // Internal attributes
        cdView.setUint32(38, 0, true);         // External attributes
        cdView.setUint32(42, offset, true);    // Relative offset of local header
        cdHeader.set(nameBytes, 46);

        cdParts.push(cdHeader);
        offset += localHeader.length + f.data.length;
      }

      const cdStart = offset;
      let cdSize = 0;
      for (const c of cdParts) cdSize += c.length;

      // End of Central Directory Record (22 bytes)
      const eocd = new Uint8Array(22);
      const eocdView = new DataView(eocd.buffer);
      eocdView.setUint32(0, 0x06054b50, true);  // EOCD signature
      eocdView.setUint16(4, 0, true);           // Disk number
      eocdView.setUint16(6, 0, true);           // Start disk
      eocdView.setUint16(8, this.files.length, true);  // Records on this disk
      eocdView.setUint16(10, this.files.length, true); // Total records
      eocdView.setUint32(12, cdSize, true);     // Central directory size
      eocdView.setUint32(16, cdStart, true);    // Central directory offset
      eocdView.setUint16(20, 0, true);          // Comment length

      // Combine all parts into single Blob
      return new Blob([...parts, ...cdParts, eocd], { type: mimeType });
    }
  }

  // --- XML Formatting Helpers ---
  function xmlEscape(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  function p(text, options = {}) {
    const { bold, size = 22, align = 'left', spacingAfter = 120, italic, color } = options;
    let rPr = `<w:rFonts w:ascii="Calibri" w:hAnsi="Calibri"/><w:sz w:val="${size}"/>`;
    if (bold) rPr += '<w:b/>';
    if (italic) rPr += '<w:i/>';
    if (color) rPr += `<w:color w:val="${color}"/>`;

    let pPr = `<w:spacing w:after="${spacingAfter}" w:line="240" w:lineRule="auto"/>`;
    if (align !== 'left') pPr += `<w:jc w:val="${align}"/>`;

    return `<w:p><w:pPr>${pPr}</w:pPr><w:r><w:rPr>${rPr}</w:rPr><w:t xml:space="preserve">${xmlEscape(text)}</w:t></w:r></w:p>`;
  }

  function sectionHeading(title) {
    return `
      <w:p>
        <w:pPr>
          <w:pBdr><w:bottom w:val="single" w:sz="8" w:space="4" w:color="333333"/></w:pBdr>
          <w:spacing w:before="180" w:after="80"/>
        </w:pPr>
        <w:r>
          <w:rPr>
            <w:rFonts w:ascii="Calibri" w:hAnsi="Calibri"/>
            <w:b/>
            <w:sz w:val="24"/>
            <w:color w:val="1E293B"/>
          </w:rPr>
          <w:t>${xmlEscape(title.toUpperCase())}</w:t>
        </w:r>
      </w:p>
    `;
  }

  function bullet(text) {
    return `
      <w:p>
        <w:pPr>
          <w:ind w:left="360" w:hanging="240"/>
          <w:spacing w:after="60"/>
        </w:pPr>
        <w:r>
          <w:rPr><w:rFonts w:ascii="Calibri"/><w:sz w:val="20"/><w:color w:val="4F46E5"/></w:rPr>
          <w:t>• </w:t>
        </w:r>
        <w:r>
          <w:rPr><w:rFonts w:ascii="Calibri"/><w:sz w:val="21"/><w:color w:val="334155"/></w:rPr>
          <w:t xml:space="preserve">${xmlEscape(text)}</w:t>
        </w:r>
      </w:p>
    `;
  }

  function jobHeader(role, company, dates) {
    return `
      <w:p>
        <w:pPr>
          <w:spacing w:before="120" w:after="40"/>
        </w:pPr>
        <w:r>
          <w:rPr><w:rFonts w:ascii="Calibri"/><w:b/><w:sz w:val="22"/><w:color w:val="0F172A"/></w:rPr>
          <w:t>${xmlEscape(role)}</w:t>
        </w:r>
        <w:r>
          <w:rPr><w:rFonts w:ascii="Calibri"/><w:i/><w:sz w:val="21"/><w:color w:val="475569"/></w:rPr>
          <w:t xml:space="preserve"> — ${xmlEscape(company)}</w:t>
        </w:r>
        <w:r>
          <w:rPr><w:rFonts w:ascii="Calibri"/><w:sz w:val="20"/><w:color w:val="64748B"/></w:rPr>
          <w:t xml:space="preserve">  |  ${xmlEscape(dates)}</w:t>
        </w:r>
      </w:p>
    `;
  }

  // --- Main Resume Synthesizer ---
  const DocxBuilder = {
    buildResumeBlob(profile, aiData) {
      const zip = new SimpleZip();
      const pData = profile.personal || {};

      // 1. Content Types
      zip.file('[Content_Types].xml', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
</Types>`);

      // 2. Package Relationships
      zip.file('_rels/.rels', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>`);

      // 3. Document Relationships
      zip.file('word/_rels/document.xml.rels', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
</Relationships>`);

      // 4. Construct word/document.xml
      let bodyXml = '';

      // Header: Full Name (Bold, 26pt, Centered)
      bodyXml += p(pData.fullName || 'Candidate Resume', {
        bold: true,
        size: 32,
        align: 'center',
        spacingAfter: 60,
        color: '0F172A'
      });

      // Contact Info Line (Centered, 19pt)
      const contactItems = [
        pData.email,
        pData.phone,
        pData.location,
        pData.linkedin,
        pData.github,
        pData.portfolio
      ].filter(Boolean);

      bodyXml += p(contactItems.join('  •  '), {
        size: 19,
        align: 'center',
        spacingAfter: 160,
        color: '64748B'
      });

      // Professional Summary
      const summaryText = (aiData && aiData.tailored_summary) 
        ? aiData.tailored_summary 
        : (pData.summary || 'Results-driven software engineering professional with experience developing scalable web applications and distributed architectures.');

      bodyXml += sectionHeading('Professional Summary');
      bodyXml += p(summaryText, { size: 21, spacingAfter: 120, color: '334155' });

      // Core Competencies / Skills
      bodyXml += sectionHeading('Core Competencies & Technical Skills');
      const skillsList = (aiData && Array.isArray(aiData.highlighted_skills) && aiData.highlighted_skills.length > 0)
        ? aiData.highlighted_skills.join(', ')
        : (pData.skills || 'JavaScript, TypeScript, React, Node.js, Python, Cloud Infrastructure, Git');

      bodyXml += p(skillsList, { size: 21, spacingAfter: 120, color: '334155' });

      // Professional Experience
      bodyXml += sectionHeading('Professional Experience');

      const experiences = profile.experience || [];
      experiences.forEach((exp, idx) => {
        const dates = `${exp.startDate || ''} – ${exp.endDate || 'Present'}`;
        bodyXml += jobHeader(exp.role || 'Software Engineer', exp.company || 'Company', dates);

        // Check if AI provided tailored bullets for this company
        let bullets = [];
        if (aiData && aiData.tailored_experience && Array.isArray(aiData.tailored_experience)) {
          const matched = aiData.tailored_experience.find(e => 
            (e.company && exp.company && e.company.toLowerCase().includes(exp.company.toLowerCase())) ||
            (e.role && exp.role && e.role.toLowerCase().includes(exp.role.toLowerCase()))
          );
          if (matched && Array.isArray(matched.bullets) && matched.bullets.length > 0) {
            bullets = matched.bullets;
          }
        }

        // Fallback to base profile bullets
        if (bullets.length === 0 && exp.bullets) {
          bullets = exp.bullets.split('\n').map(b => b.trim()).filter(b => b.length > 0);
        }

        // Append bullets
        bullets.forEach(b => {
          const cleanBullet = b.replace(/^[•\-\*]\s*/, '');
          bodyXml += bullet(cleanBullet);
        });
      });

      // Education
      if (pData.education) {
        bodyXml += sectionHeading('Education');
        bodyXml += p(pData.education, { size: 21, bold: true, spacingAfter: 60, color: '0F172A' });
      }

      // Assemble full XML
      const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    ${bodyXml}
    <w:sectPr>
      <w:pgSz w:w="12240" w:h="15840"/>
      <w:pgMar w:top="1080" w:right="1080" w:bottom="1080" w:left="1080" w:header="720" w:footer="720" w:gutter="0"/>
    </w:sectPr>
  </w:body>
</w:document>`;

      zip.file('word/document.xml', documentXml);

      // Return generated Blob
      return zip.generateBlob();
    }
  };

  // Export to window or module
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = DocxBuilder;
  } else {
    window.DocxBuilder = DocxBuilder;
  }
})();
